using MiniCompiler.IR; using SemanticContracts; using SemanticQueries.Core; namespace Packages.BranchSimplifier; public sealed class BranchSimplificationPass{private static readonly RangeQuery Q=new();public bool? IsAlwaysTrue(LessThanCondition c,SemanticSession s){var r=s.Query(Q,new(c.Value,c.Point));if(r.Status!=QueryStatus.Known)return null;return r.Value!.Upper<c.Constant?true:r.Value.Lower>=c.Constant?false:null;}}